// src/util/ThreadSleep.ts
class ThreadSleep {
  static async sleepPrecise(ms) {
    if (ms <= 0) {
      return;
    }
    if (ms % 10 === 0) {
      await ThreadSleep.sleep(ms - 1);
      await ThreadSleep.sleep(1);
    } else {
      await ThreadSleep.sleep(ms);
    }
  }
  static async sleep(ms) {
    try {
      await new Promise((resolve) => setTimeout(resolve, ms));
    } catch (var2) {}
  }
}

// src/util/Timer.ts
class Timer {
  ntime = performance.now() * 1e6;
  async count(mindel, deltime) {
    const mindelNs = mindel * 1e6;
    let delta = this.ntime - performance.now() * 1e6;
    let loops = 0;
    if (delta < mindelNs) {
      delta = mindelNs;
    }
    await ThreadSleep.sleepPrecise(delta / 1e6 | 0);
    const now = performance.now() * 1e6;
    while (loops < 10 && (loops < 1 || this.ntime < now)) {
      loops++;
      this.ntime += deltime * 1e6;
    }
    if (now > this.ntime) {
      this.ntime = now;
    }
    return loops;
  }
  reset() {
    this.ntime = performance.now() * 1e6;
  }
}

